const sd = $getWorkflowStaticData('global');
const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];

const categorias = [
  { nome: 'Desenvolvimento web com React e TypeScript', imagens: ['code on dark monitor', 'javascript code screen', 'web developer laptop', 'programming workspace', 'colorful code editor', 'frontend developer desk'] },
  { nome: 'Automação de processos com n8n e APIs', imagens: ['workflow diagram', 'automation gears', 'connected network nodes', 'data flow abstract', 'api integration', 'robot arm automation'] },
  { nome: 'Inteligência Artificial aplicada ao desenvolvimento de software', imagens: ['artificial intelligence', 'processor chip', 'neural network abstract', 'robot and human', 'machine learning', 'futuristic technology'] },
  { nome: 'Boas práticas de código e arquitetura de software', imagens: ['whiteboard planning', 'software architecture diagram', 'developer desk setup', 'code review team', 'blueprint plan', 'programming team'] },
  { nome: 'Linux, Docker e infraestrutura para quem desenvolve', imagens: ['server room', 'data center', 'network cables', 'terminal screen', 'cloud computing', 'fiber optic'] },
  { nome: 'Segurança para quem desenvolve software', imagens: ['padlock security', 'cyber security shield', 'password login', 'two factor authentication', 'encryption code', 'fingerprint scanner'] },
  { nome: 'Carreira e produtividade em desenvolvimento de software', imagens: ['home office', 'notebook planner', 'team meeting', 'coffee desk', 'online learning', 'headphones work'] },
];

const formatosManha = [
  'dica rápida com lista curta de 3 a 5 itens',
  'mito x verdade sobre o assunto',
  'erro comum que as pessoas cometem e como evitar',
  'mini passo a passo prático',
  'checklist para o leitor aplicar hoje',
];
const formatosNoite = [
  'curiosidade surpreendente explicada de forma leve, sem números inventados',
  'reflexão em primeira pessoa, sem inventar fatos específicos',
  'explicação simples usando uma analogia do dia a dia',
  'pergunta provocativa seguida da resposta',
  'conversa direta com o leitor, como um conselho a um amigo',
];
const formatosBastidor = [
  'como uma parte específica do projeto funciona por dentro',
  'uma decisão técnica do projeto e o motivo dela, conforme o material',
  'o problema que o projeto resolve e o caminho escolhido para resolver',
  'uma limitação assumida do projeto e por que ela existe, conforme o material',
];
const formatosCarrossel = [
  'passo a passo em etapas, uma etapa por slide',
  'erros comuns e como evitar, um erro por slide',
  'checklist prático, um item por slide',
  'mitos e verdades, um por slide',
  'comparação entre duas abordagens, um critério por slide',
];
const formatosEnquete = [
  'pergunta de opinião sobre uma escolha técnica do dia a dia',
  'pergunta sobre um hábito de trabalho de quem desenvolve',
  'pergunta sobre qual abordagem a pessoa usa hoje em um problema comum',
];
// um post por dia: dias pares = dicas práticas, dias ímpares = reflexões
const manha = $now.ordinal % 2 === 0;
const tons = ['didático e calmo', 'descontraído e bem-humorado', 'direto e objetivo', 'curioso e entusiasmado', 'sério e alerta, sem causar pânico'];
const ganchos = ['uma pergunta curiosa', 'uma frase curta e inesperada', 'um erro comum', 'uma situação do cotidiano', 'uma afirmação que quebra um mito', 'um "e se" interessante'];
const tamanhos = {
  curto: 'curto, entre 250 e 500 caracteres, em 2 a 4 parágrafos bem curtos e sem lista',
  medio: 'médio, entre 600 e 1000 caracteres',
  longo: 'longo, entre 1000 e 1500 caracteres',
  legenda: 'curto, entre 300 e 600 caracteres. É a legenda do carrossel: apresenta o assunto e dá vontade de abrir os slides, sem repetir o conteúdo deles',
  enquete: 'curto, entre 220 e 450 caracteres. Dá o contexto da pergunta da enquete e convida a votar e comentar o motivo',
};

const ultimas = Array.isArray(sd.ultimasCategorias) ? sd.ultimasCategorias : [];
let candidatas = categorias.filter(c => !ultimas.includes(c.nome));
if (!candidatas.length) candidatas = categorias;
const cat = pick(candidatas);

// evita repetir formato e tipo de abertura dos últimos posts
const semRepetir = (lista, usados) => { const livres = lista.filter(x => !usados.includes(x)); return livres.length ? livres : lista; };
const ultimosFormatos = Array.isArray(sd.ultimosFormatos) ? sd.ultimosFormatos : ['pergunta provocativa seguida da resposta'];
const ultimosGanchos = Array.isArray(sd.ultimosGanchos) ? sd.ultimosGanchos : ['um "e se" interessante', 'uma pergunta curiosa'];
const aberturas = Array.isArray(sd.ultimasAberturas) ? sd.ultimasAberturas : ['E se aquela rede', 'E se a melhor'];

// projetos públicos do GitHub: repositório novo entra sozinho na fila dos posts de bastidor
const DONO = 'leomagalhaesti';
let projetos = [];
try {
  projetos = $('Buscar projetos no GitHub').all().map(i => i.json)
    .filter(r => r && r.name && !r.fork && !r.archived && !r.private && r.name.toLowerCase() !== DONO)
    // só projetos com atividade no último ano, para não puxar exercícios antigos
    .filter(r => r.pushed_at && (Date.now() - new Date(r.pushed_at).getTime()) < 365 * 24 * 3600 * 1000)
    .map(r => ({ repo: r.name, descricao: r.description || '', ramo: r.default_branch || 'main' }));
} catch (e) { projetos = []; }

// tipo do post: foto (texto com foto), texto (sem imagem), bastidor (sobre um projeto meu),
// carrossel (PDF com slides) ou enquete
const ultimosTipos = Array.isArray(sd.ultimosTipos) ? sd.ultimosTipos : ['foto', 'foto', 'foto'];
const pesos = { foto: 35, texto: 22, bastidor: 18, carrossel: 17, enquete: 8 };
if (ultimosTipos.slice(0, 2).includes('carrossel')) delete pesos.carrossel;
if (ultimosTipos.slice(0, 6).includes('enquete')) delete pesos.enquete;
if (!projetos.length || ultimosTipos.slice(0, 3).includes('bastidor')) delete pesos.bastidor;
if (ultimosTipos[0] && ultimosTipos[0] === ultimosTipos[1]) delete pesos[ultimosTipos[0]];
const sortearPeso = (p) => {
  let r = Math.random() * Object.values(p).reduce((a, b) => a + b, 0);
  for (const [k, v] of Object.entries(p)) { r -= v; if (r < 0) return k; }
  return Object.keys(p)[0];
};
const tipo = sortearPeso(pesos);

const ultimosProjetos = Array.isArray(sd.ultimosProjetos) ? sd.ultimosProjetos : [];
const projeto = projetos.length ? pick(semRepetir(projetos.map(p => p.repo), ultimosProjetos.slice(0, Math.max(0, projetos.length - 1)))) : '';
const dadosProjeto = tipo === 'bastidor' ? (projetos.find(p => p.repo === projeto) || null) : null;

const tamanho = pick({ foto: ['medio', 'longo'], texto: ['curto', 'curto', 'medio'], bastidor: ['medio', 'longo'], carrossel: ['legenda'], enquete: ['enquete'] }[tipo]);
const formatosDoTipo = { bastidor: formatosBastidor, carrossel: formatosCarrossel, enquete: formatosEnquete }[tipo] || (manha ? formatosManha : formatosNoite);

// título de uma página do Notion, em qualquer formato de saída do nó
const tituloDe = (j) => {
  if (!j) return '';
  if (j.properties) {
    for (const p of Object.values(j.properties)) {
      if (p && p.type === 'title' && Array.isArray(p.title)) return p.title.map(t => t.plain_text || '').join('');
    }
  }
  return j.name || j.Name || j.Nome || j.property_name || j.property_nome || j.title || '';
};

const doNotion = $input.all().map(i => String(tituloDe(i.json)).trim()).filter(Boolean);
const memoria = Array.isArray(sd.temas) ? sd.temas : [];
const temas = [...new Set([...memoria, ...doNotion])].slice(0, 80);

return [{
  json: {
    tipo,
    tamanho,
    tamanhoTexto: tamanhos[tamanho],
    area: tipo === 'bastidor' ? 'Bastidor do projeto ' + projeto : cat.nome,
    areaReserva: cat.nome,
    projeto: dadosProjeto,
    readmeUrl: dadosProjeto
      ? 'https://raw.githubusercontent.com/' + DONO + '/' + dadosProjeto.repo + '/' + dadosProjeto.ramo + '/README.md'
      : 'https://raw.githubusercontent.com/' + DONO + '/' + DONO + '/main/README.md',
    formato: pick(semRepetir(formatosDoTipo, ultimosFormatos)),
    formatoReserva: pick(semRepetir(manha ? formatosManha : formatosNoite, ultimosFormatos)),
    tom: pick(tons),
    gancho: pick(semRepetir(ganchos, ultimosGanchos)),
    aberturasRecentes: aberturas.length ? aberturas.map(t => '- ' + t).join('\n') : '(nenhuma ainda)',
    dicaImagem: pick(cat.imagens),
    temasAnteriores: temas.length ? temas.map(t => '- ' + t).join('\n') : '(nenhum ainda)',
  },
}];

const entrada = $input.first().json;
const tema = $('Montar pedido da IA').first().json;

const partes = (entrada.candidates && entrada.candidates[0] && entrada.candidates[0].content && entrada.candidates[0].content.parts) || [];
let txt = partes.filter(p => !p.thought).map(p => p.text || '').join('');
if (typeof txt !== 'string' || !txt.trim()) {
  throw new Error('A IA não devolveu texto (' + JSON.stringify(entrada.promptFeedback || entrada.error || '').slice(0, 200) + '). Verifique a chave do Gemini e o limite diário gratuito.');
}
txt = txt.replace(/\r/g, '').trim();

const pega = (re) => { const r = txt.match(re); return r ? r[1].trim() : ''; };
let titulo = pega(/^\s*T[IÍ]TULO:\s*(.+)$/im);
let busca = pega(/^\s*BUSCA:\s*(.+)$/im);
const iPost = txt.search(/^\s*POST:/im);
let post = iPost >= 0 ? txt.slice(iPost).replace(/^\s*POST:\s*/i, '') : '';
// carrossel e enquete trazem um bloco a mais depois do texto do post
let bloco = '';
const iBloco = post.search(/^\s*(SLIDES|ENQUETE):/im);
if (iBloco >= 0) { bloco = post.slice(iBloco); post = post.slice(0, iBloco); }

const limparTexto = (s) => String(s || '')
  .replace(/\*\*/g, '')
  .replace(/^#{1,6}\s+/gm, '')
  .replace(/[()\[\]{}<>|~*_@\\]/g, ' ')
  .replace(/[ \t]{2,}/g, ' ')
  .replace(/ +\n/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

post = limparTexto(post);
// resposta cortada pelo limite de tokens: fica só até o último parágrafo completo
const cortada = entrada.candidates[0].finishReason === 'MAX_TOKENS';
if (cortada) {
  const paragrafos = post.split('\n\n');
  while (paragrafos.length && !/[.!?…]$/.test(paragrafos[paragrafos.length - 1].trim())) paragrafos.pop();
  post = paragrafos.join('\n\n').trim();
}
titulo = limparTexto(titulo).replace(/^\s*tecnologia\s*:\s*/i, '').replace(/\n/g, ' ').slice(0, 80).trim();

if (!post || post.length < 200) throw new Error('O post veio vazio ou curto demais (' + post.length + ' caracteres). Resposta da IA: ' + txt.slice(0, 200));
if (!titulo) throw new Error('A IA não devolveu a linha TITULO. Resposta da IA: ' + txt.slice(0, 200));
if (post.length > 2700) {
  const corte = post.lastIndexOf('\n\n', 2700);
  post = post.slice(0, corte > 500 ? corte : 2700).trim();
}

// slides do carrossel e enquete; se vierem fora do formato, o post sai como texto simples
let tipo = tema.tipo, slides = [], enquete = null;
const linha = (s) => limparTexto(s).replace(/#/g, '').replace(/\s+/g, ' ').trim();
if (tipo === 'carrossel') {
  slides = cortada ? [] : bloco.replace(/^\s*SLIDES:\s*/i, '').split(/^\s*SLIDE\s*\d+\s*:/im).map(b => b.trim()).filter(Boolean).map(b => {
    const l = b.split('\n').map(x => x.trim()).filter(Boolean);
    return { titulo: linha(l[0] || '').slice(0, 90), texto: linha(l.slice(1).join(' ')).slice(0, 320) };
  }).filter(s => s.titulo && s.texto).slice(0, 8);
  if (slides.length < 4) { tipo = 'texto'; slides = []; }
}
if (tipo === 'enquete') {
  const pergunta = linha((bloco.match(/^\s*ENQUETE:\s*(.+)$/im) || [])[1] || '');
  const opcoes = [...new Set((bloco.split(/^\s*OP[CÇ][OÕ]ES:\s*$/im)[1] || '').split('\n').map(o => linha(o.replace(/^\s*[-•]\s*/, ''))).filter(o => o && o.length <= 30))].slice(0, 4);
  if (cortada || !pergunta || pergunta.length > 140 || opcoes.length < 2) tipo = 'texto';
  else enquete = { pergunta, opcoes };
}

// texto de reserva: se o carrossel ou a enquete não puderem ser publicados, o post sai só com o texto,
// sem as frases que falam de slides ou de votação
const semMencao = (t) => t.split('\n\n').map(par => par.split('\n').map(l => l.split(/(?<=[.!?])\s+/).filter(f => !/enquete|vot[eao]|arrast|desliz|slide|carrossel/i.test(f)).join(' ')).filter(Boolean).join('\n')).filter(Boolean).join('\n\n');
const postReserva = ['carrossel', 'enquete'].includes(tema.tipo) ? semMencao(post) : '';
if (tipo !== tema.tipo && postReserva.length >= 150) post = postReserva;

// post de bastidor leva o link do repositório, antes da linha de hashtags
if (tema.tipo === 'bastidor' && tema.projeto) {
  const link = 'Código no GitHub: https://github.com/leomagalhaesti/' + tema.projeto.repo;
  const linhas = post.split('\n');
  if (linhas.length > 1 && linhas[linhas.length - 1].trim().startsWith('#')) {
    linhas.splice(linhas.length - 1, 0, link, '');
    post = linhas.join('\n').replace(/\n{3,}/g, '\n\n');
  } else {
    post = post + '\n\n' + link;
  }
}

busca = busca.replace(/[^a-zA-Z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim().toLowerCase();
if (!busca) busca = tema.dicaImagem;

return [{ json: { titulo, post, buscaImagem: busca, area: tema.area, tipo, tamanho: tema.tamanho, projeto: tema.projeto ? tema.projeto.repo : '', slides, enquete, postReserva } }];

const sd = $getWorkflowStaticData('global');
const usadas = Array.isArray(sd.fotosUsadas) ? sd.fotosUsadas : [];
const idsUsados = new Set(usadas.map(f => String(f.id)));

const lerHits = (nome) => {
  try { const h = $(nome).first().json.hits; return Array.isArray(h) ? h : []; } catch (e) { return []; }
};
const valida = (h) => h && h.id && h.largeImageURL;
const h1 = lerHits('Buscar fotos do tema').filter(valida);
const h2 = lerHits('Buscar fotos de reserva').filter(valida);

const todas = [];
const vistos = new Set();
for (const h of [...h1, ...h2]) { if (!vistos.has(h.id)) { vistos.add(h.id); todas.push(h); } }

if (!todas.length) {
  throw new Error('O Pixabay não retornou fotos. Confira a chave do Pixabay (credencial Query Auth com nome "key") e o limite de requisições.');
}

const livres = (arr) => arr.filter(h => !idsUsados.has(String(h.id)));
let candidatas = livres(h1);
if (!candidatas.length) candidatas = livres(h2);
if (!candidatas.length) {
  // todas já foram usadas: pega a usada há mais tempo
  const ordem = new Map(usadas.map((f, i) => [String(f.id), i]));
  candidatas = [...todas].sort((a, b) => (ordem.get(String(a.id)) ?? -1) - (ordem.get(String(b.id)) ?? -1)).slice(0, 1);
}

const foto = candidatas[Math.floor(Math.random() * candidatas.length)];
const nome = String(foto.user || 'autor desconhecido').replace(/[()\[\]{}<>|~*_@\\#]/g, ' ').replace(/\s+/g, ' ').trim();

return [{ json: { fotoId: foto.id, fotoUrl: foto.largeImageURL, fotografo: nome } }];

const sd = $getWorkflowStaticData('global');
const post = $('Validar e limpar post').first().json;
const temFoto = post.tipo === 'foto';
const foto = temFoto ? $('Escolher foto').first().json : {};

if (temFoto) sd.fotosUsadas = [...(Array.isArray(sd.fotosUsadas) ? sd.fotosUsadas : []), { id: foto.fotoId, data: $today.toFormat('yyyy-MM-dd') }].slice(-300);
sd.temas = [post.titulo, ...(Array.isArray(sd.temas) ? sd.temas : [])].slice(0, 80);
sd.ultimasCategorias = [post.area, ...(Array.isArray(sd.ultimasCategorias) ? sd.ultimasCategorias : [])].slice(0, 3);
const temaDoDia = $('Montar pedido da IA').first().json;
sd.ultimosFormatos = [temaDoDia.formato, ...(Array.isArray(sd.ultimosFormatos) ? sd.ultimosFormatos : [])].slice(0, 3);
sd.ultimosGanchos = [temaDoDia.gancho, ...(Array.isArray(sd.ultimosGanchos) ? sd.ultimosGanchos : [])].slice(0, 3);
sd.ultimosTipos = [post.tipo, ...(Array.isArray(sd.ultimosTipos) ? sd.ultimosTipos : ['foto', 'foto', 'foto'])].slice(0, 8);
if (post.projeto) sd.ultimosProjetos = [post.projeto, ...(Array.isArray(sd.ultimosProjetos) ? sd.ultimosProjetos : [])].slice(0, 6);
const abertura = String(post.post || '').trim().split(/\s+/).slice(0, 4).join(' ');
sd.ultimasAberturas = [abertura, ...(Array.isArray(sd.ultimasAberturas) ? sd.ultimasAberturas : ['E se aquela rede', 'E se a melhor'])].slice(0, 6);

return [{ json: { registrado: true, tipo: post.tipo, fotoId: foto.fotoId || '', titulo: post.titulo } }];

// Monta o PDF do carrossel direto em código, sem navegador: uma página 1080x1350 por slide.
const post = $('Validar e limpar post').first().json;
const envio = $input.first().json.value || {};
if (!envio.uploadUrl || !envio.document) throw new Error('O LinkedIn não devolveu o endereço de envio do PDF.');
const slides = post.slides || [];
if (slides.length < 4) throw new Error('Carrossel com menos de 4 slides.');

const W = 1080, H = 1350, M = 96;
// larguras das letras da Helvetica (códigos 32 a 126), para quebrar as linhas no lugar certo
const LARG = {
  n: [278,278,355,556,556,889,667,191,333,333,389,584,278,333,278,278,556,556,556,556,556,556,556,556,556,556,278,278,584,584,584,556,1015,667,667,722,722,667,611,778,722,278,500,667,556,833,722,778,667,778,722,667,611,722,667,944,667,667,611,278,278,278,469,556,333,556,556,500,556,556,278,556,556,222,222,500,222,833,556,556,556,556,333,500,278,556,500,722,500,500,500,334,260,334,584],
  b: [278,333,474,556,556,889,722,238,333,333,389,584,278,333,278,278,556,556,556,556,556,556,556,556,556,556,333,333,584,584,584,611,975,722,722,722,722,667,611,778,722,278,556,722,611,833,722,778,667,778,722,667,611,722,667,944,667,667,611,333,278,333,584,556,333,556,611,556,611,556,333,611,611,278,278,556,278,889,611,611,611,611,389,556,333,611,556,778,556,556,500,389,280,389,584],
};
const CP1252 = { '–': 0x96, '—': 0x97, '‘': 0x91, '’': 0x92, '“': 0x93, '”': 0x94, '•': 0x95, '…': 0x85 };
// o PDF usa a codificação WinAnsi: mantém acentos do português e descarta emojis
const codigos = (s) => { const o = []; for (const ch of String(s)) { const c = ch.codePointAt(0); if (CP1252[ch]) o.push(CP1252[ch]); else if (c >= 32 && c <= 126 || c >= 160 && c <= 255) o.push(c); } return o; };
const base = (c) => c < 127 ? c : (String.fromCharCode(c).normalize('NFD').charCodeAt(0));
const largura = (s, f, tam) => codigos(s).reduce((t, c) => { const b = base(c); return t + (b >= 32 && b <= 126 ? LARG[f][b - 32] : 556); }, 0) * tam / 1000;
const hex = (s) => '<' + codigos(s).map(c => c.toString(16).padStart(2, '0')).join('') + '>';
const quebrar = (texto, f, tam, max) => {
  const linhas = []; let atual = '';
  for (const p of String(texto).replace(/\s+/g, ' ').trim().split(' ')) {
    const tenta = atual ? atual + ' ' + p : p;
    if (largura(tenta, f, tam) <= max || !atual) atual = tenta; else { linhas.push(atual); atual = p; }
  }
  if (atual) linhas.push(atual);
  return linhas;
};
// diminui a letra até o texto caber no número máximo de linhas
const ajustar = (texto, f, tam, min, max, maxLinhas) => { let l; for (;; tam -= 4) { l = quebrar(texto, f, tam, max); if (l.length <= maxLinhas || tam <= min) break; } return { linhas: l.slice(0, maxLinhas), tam }; };
const cor = (h) => [1, 3, 5].map(i => (parseInt(h.slice(i, i + 2), 16) / 255).toFixed(3)).join(' ');
const FUNDO = '#10222A', FUNDO2 = '#171A27', VERDE = '#72B875', LIMA = '#B8E05F', CLARO = '#F4F7F8', SUAVE = '#C9D6D8';

const paginas = slides.map((s, i) => {
  const c = []; const total = slides.length, capa = i === 0;
  const ret = (h, x, y, w, a) => c.push(cor(h) + ' rg ' + x + ' ' + y + ' ' + w + ' ' + a + ' re f');
  const txt = (t, f, tam, h, x, y) => c.push('BT /' + (f === 'b' ? 'F2' : 'F1') + ' ' + tam + ' Tf ' + cor(h) + ' rg ' + x.toFixed(1) + ' ' + y.toFixed(1) + ' Td ' + hex(t) + ' Tj ET');
  ret(capa ? FUNDO2 : FUNDO, 0, 0, W, H);
  ret(VERDE, 0, H - 18, W, 18);
  let y = H - M - 60;
  if (capa) {
    ret(LIMA, M, y - 150, 120, 10);
    y -= 300;
    const t = ajustar(s.titulo, 'b', 104, 64, W - 2 * M, 5);
    for (const l of t.linhas) { txt(l, 'b', t.tam, CLARO, M, y); y -= t.tam * 1.14; }
    y -= 40;
    const sub = ajustar(s.texto, 'n', 46, 34, W - 2 * M, 4);
    for (const l of sub.linhas) { txt(l, 'n', sub.tam, SUAVE, M, y); y -= sub.tam * 1.4; }
  } else {
    txt(String(i).padStart(2, '0'), 'b', 150, VERDE, M, y - 110);
    y -= 300;
    const t = ajustar(s.titulo, 'b', 76, 52, W - 2 * M, 3);
    for (const l of t.linhas) { txt(l, 'b', t.tam, CLARO, M, y); y -= t.tam * 1.16; }
    ret(LIMA, M, y + 10, 90, 8);
    y -= 80;
    const b = ajustar(s.texto, 'n', 54, 38, W - 2 * M, 9);
    for (const l of b.linhas) { txt(l, 'n', b.tam, SUAVE, M, y); y -= b.tam * 1.45; }
  }
  // rodapé: autor, barra de progresso e indicação de página
  ret('#20343A', M, 150, W - 2 * M, 6);
  ret(VERDE, M, 150, (W - 2 * M) * (i + 1) / total, 6);
  txt('Leonardo Magalhães', 'b', 30, CLARO, M, 88);
  const dir = i < total - 1 ? 'Arraste para o lado »' : (i + 1) + ' de ' + total;
  txt(dir, 'n', 30, i < total - 1 ? LIMA : SUAVE, W - M - largura(dir, 'n', 30), 88);
  return c.join('\n');
});

// estrutura do arquivo PDF
const objs = [];
const add = (corpo) => { objs.push(corpo); return objs.length; };
add('<< /Type /Catalog /Pages 2 0 R >>');
add('');
add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>');
add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>');
const kids = [];
for (const conteudo of paginas) {
  const nc = add('<< /Length ' + conteudo.length + ' >>\nstream\n' + conteudo + '\nendstream');
  kids.push(add('<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ' + W + ' ' + H + '] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> >> /Contents ' + nc + ' 0 R >>'));
}
objs[1] = '<< /Type /Pages /Count ' + kids.length + ' /Kids [' + kids.map(k => k + ' 0 R').join(' ') + '] >>';
let pdf = '%PDF-1.4\n'; const pos = [];
objs.forEach((o, i) => { pos.push(pdf.length); pdf += (i + 1) + ' 0 obj\n' + o + '\nendobj\n'; });
const xref = pdf.length;
pdf += 'xref\n0 ' + (objs.length + 1) + '\n0000000000 65535 f \n' + pos.map(p => String(p).padStart(10, '0') + ' 00000 n \n').join('');
pdf += 'trailer\n<< /Size ' + (objs.length + 1) + ' /Root 1 0 R >>\nstartxref\n' + xref + '\n%%EOF\n';

const nome = String(post.titulo || 'carrossel').normalize('NFD').replace(/[^a-zA-Z0-9 ]/g, '').trim().replace(/\s+/g, '-').toLowerCase().slice(0, 60) + '.pdf';
return [{
  json: { uploadUrl: envio.uploadUrl, document: envio.document, paginas: paginas.length, arquivo: nome },
  binary: { data: { data: Buffer.from(pdf, 'latin1').toString('base64'), mimeType: 'application/pdf', fileName: nome, fileExtension: 'pdf' } },
}];
